import crypto from 'node:crypto';
import express from 'express';
import nodemailer from 'nodemailer';
import type { Pool, RowDataPacket } from 'mysql2/promise';

const ADMIN_COOKIE = 'admin_auth';
const ADMIN_SESSION_MINUTES = 10;
const ADMIN_SESSION_MAX_AGE = ADMIN_SESSION_MINUTES * 60 * 1000;
const ADMIN_ROLES = [
  { value: 'requester', label: '요청자' },
  { value: 'manager', label: '부서장' },
  { value: 'director', label: '국장' },
  { value: 'secretary', label: '비서실' },
  { value: 'scheduler', label: '일정관리자' },
  { value: 'executive', label: '의사결정권자' },
] as const;
const ADMIN_ROLE_VALUES = ADMIN_ROLES.map(({ value }) => value);
const ADMIN_ROLE_LABELS = Object.fromEntries(ADMIN_ROLES.map(({ value, label }) => [value, label])) as Record<string, string>;

function esc(value: unknown): string {
  return String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;');
}

function secret(): string {
  return process.env.APP_AUTH_SECRET || process.env.SUPERVISOR_PASSWORD || 'change-this-app-secret';
}

function digest(value: string): string {
  return crypto.createHmac('sha256', secret()).update(value).digest('hex');
}

function isValidEmail(value: string): boolean {
  return value.length <= 255 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function passwordHash(password: string, salt = crypto.randomBytes(16).toString('hex')): string {
  return `${salt}:${crypto.scryptSync(password, salt, 64).toString('hex')}`;
}

function cookieToken(request: express.Request): string | null {
  const raw = request.headers.cookie?.split(';').map((v) => v.trim()).find((v) => v.startsWith(`${ADMIN_COOKIE}=`))?.slice(ADMIN_COOKIE.length + 1);
  return raw ? decodeURIComponent(raw) : null;
}

async function adminDistrict(db: Pool, request: express.Request): Promise<number | null> {
  const token = cookieToken(request);
  if (!token) return null;
  const [rows] = await db.query('SELECT district_seq AS districtSeq FROM admin_sessions WHERE token_hash=? AND expires_at>NOW() LIMIT 1', [digest(token)]);
  const row = (rows as Array<{ districtSeq: number }>)[0];
  if (!row) return null;
  return row.districtSeq;
}

function requestIp(request: express.Request): string {
  const forwarded = request.headers['x-forwarded-for'];
  return String(Array.isArray(forwarded) ? forwarded[0] : forwarded?.split(',')[0] || request.ip || request.socket.remoteAddress || '').trim().slice(0, 64);
}

async function finalizeExpiredAdminSessions(db: Pool): Promise<void> {
  await db.query("UPDATE admin_login_history h JOIN admin_sessions s ON s.history_id=h.id SET h.logout_at=COALESCE(h.logout_at,s.expires_at),h.logout_reason=COALESCE(h.logout_reason,'timeout') WHERE s.expires_at<=NOW()");
  await db.query('DELETE FROM admin_sessions WHERE expires_at<=NOW()');
}

async function sendMail(to: string, subject: string, text: string, html?: string): Promise<boolean> {
  const host = process.env.SMTP_HOST;
  if (!host) {
    console.log(`[개발용 메일] 수신: ${to}\n제목: ${subject}\n${text}`);
    return false;
  }
  const port = Number(process.env.SMTP_PORT ?? 587);
  const transporter = nodemailer.createTransport({
    host,
    port,
    secure: process.env.SMTP_SECURE ? process.env.SMTP_SECURE === 'true' : port === 465,
    auth: process.env.SMTP_USER ? { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS ?? process.env.SMTP_PASSWORD ?? '' } : undefined,
  });
  const fromAddress = process.env.SMTP_FROM || process.env.SMTP_USER;
  const from = process.env.SMTP_FROM_NAME && fromAddress
    ? { name: process.env.SMTP_FROM_NAME, address: fromAddress }
    : fromAddress;
  const isLoginCodeMail = subject.includes('계정이 발급') || subject.includes('임시 비밀번호 재발급');
  const initialCode = isLoginCodeMail ? text.match(/임시 비밀번호(?::|는)\s*(\S+?)(?:입니다|\s|$)/)?.[1] : undefined;
  const messageHtml = html ?? (initialCode ? initialLoginCodeEmail(to, initialCode) : undefined);
  await transporter.sendMail({ from, to, subject, text, html: messageHtml });
  return true;
}

